const CLAUDE_DEFAULT_TITLE = "Claude Code";

// Spinner glyphs (braille dots, asterisks, stars, ...) that Claude Code and
// other harnesses prepend to the terminal title while a turn is running.
const LEADING_GLYPH = /^[^\p{L}\p{N}]+/u;

function normalizeClaudeTitle(title: string): string {
	return title.replace(LEADING_GLYPH, "").trim();
}

/**
 * Extracts the human-readable task title from a terminal window title.
 *
 * Returns null when the title carries no useful task information (for example
 * the bare application name or an empty title).
 */
export function taskTitle(app: string, title: string): string | null {
	const trimmed = title.trim();
	if (!trimmed) return null;

	if (app === "claude") {
		const task = normalizeClaudeTitle(trimmed);
		if (!task || task === CLAUDE_DEFAULT_TITLE) return null;
		return task;
	}

	if (app === "pi") {
		// Pi titles look like `<app> - <session name> - <folder>`.
		const parts = trimmed.split(" - ");
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session || null;
	}

	return null;
}

